#!/usr/bin/env python3
"""Freeze review assignments without launching or accepting reviewers."""
import sys
sys.dont_write_bytecode=True
import importlib.util,pathlib,json,math
P=pathlib.Path(__file__).resolve().parent
sp=importlib.util.spec_from_file_location('w',P/'step-03-wave2-check.py');w=importlib.util.module_from_spec(sp);sp.loader.exec_module(w);m=w.m;m.SETS=w.WAVE2
PIN=w.PIN

def main():
 rs=m.records();manifest=json.loads((P/'step-03-wave2-manifest.json').read_text());assert manifest==w.freeze(rs);by={r['file']:r for r in rs};rows=[];account=[]
 for g in manifest['sets']:
  batch=g['set'];u=manifest['unpatchedStrata'][batch.removeprefix('batch-')];selected=sorted(set(g['selected']+u['selected']))
  account.append({'set':batch,'allFiles':sum(r['reviewSet']==batch for r in rs),'retiringFiles':sum(r['reviewSet']==batch and bool(r.get('retiresWithTree')) for r in rs),'patchedPopulation':g['populationCount'],'patchedSeedSample':len(g['sample']),'mandatoryFiles':len(g['mandatoryWitnesses']),'patchedAndMandatoryDistinct':len(g['selected']),'unpatchedEligiblePopulation':u['populationCount'],'unpatchedSample':len(u['selected']),'distinctSelected':len(selected),'selectedFileDenominator':len(selected),'reviewedFileDenominator':0,'reviewedFiles':0,'patchedStratum':{'population':g['populationCount'],'seededSample':len(g['sample']),'mandatoryUnionSelected':len(g['selected']),'reviewedDenominator':0,'reworkNumerator':'pending'},'unpatchedStratum':{'eligiblePopulation':u['populationCount'],'sample':len(u['selected']),'reviewedDenominator':0,'reworkNumerator':'pending'},'reworkNumerator':'pending independent review','threshold':'≤3% within each set and stratum; >3% expands to every surviving file in that set, including zero-edge files; no pooling or reseeding'})
  for file in selected:
   r=by[file];b=(json.dumps(r,ensure_ascii=False,separators=(',',':'))+'\n').encode();strata=[]
   if file in g['sample']:strata.append('patched-seeded')
   if file in [x['file'] for x in g['mandatoryWitnesses']]:strata.append('mandatory-threshold')
   if file in u['selected']:strata.append('unpatched-seeded')
   rows.append({'file':file,'set':batch,'strata':strata,'edges':m.edge_count(r),'recordSha256':m.sha(b),'sourceDigest':r['digest'],'diffSha256':m.sha(r['diff']),'recordBytes':len(b),'sourceBytes':len(m.blob(PIN,file)),'contextPlusRecordBytes':len(b)+len(m.blob(PIN,file))})
 parts=[];current=[]
 for row in rows:
  if current and (len(current)>=6 or sum(x['edges'] for x in current)+row['edges']>150 or sum(x['contextPlusRecordBytes'] for x in current)+row['contextPlusRecordBytes']>400000):parts.append(current);current=[]
  current.append(row)
 if current:parts.append(current)
 result={'pin':PIN,'manifest':'step-03-wave2-manifest.json','selectedFiles':len(rows),'selectedEdges':sum(x['edges'] for x in rows),'perSet':account,'parts':[],'reviewersStarted':0,'accepted':0,'semanticAcceptance':'Pending Lead; author freezes membership only.'}
 for n,part in enumerate(parts,1):
  name=f'review-a38-step-03-wave2-p{n:02}.md'
  assert not (P/name).exists(),'review output already exists; never overwrite another review'
  result['parts'].append({'part':n,'report':str(m.REL/name),'files':part,'fileCount':len(part),'edges':sum(x['edges'] for x in part),'sourcePlusRecordBytes':sum(x['contextPlusRecordBytes'] for x in part),'recordBytes':sum(x['recordBytes'] for x in part)})
 (P/'step-03-wave2-review-index.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
 lines=['# Step 3 wave 2 — one independent A51 review request','',f'Author pin `{PIN}`. Records only; no consumer edit. Reviewers started/accepted: **0/0**. Read owner A51, L12-10 and L12-21..L12-36 in `owner-answers.md`, the current authoring rules digest in `progress.md`, and the schema in `step-03-authoring-request.md`. Historical author checkpoints do not override the latest rulings.','',f'Packet: **{len(rows)} selected whole files / {sum(x["edges"] for x in rows)} edges / {len(parts)} parts**. The frozen manifest contains every per-set seed, full rank, sample, mandatory witness, source/diff/record hash and both strata. `step-03-wave2-review-index.json` binds exact assignment membership and measured bytes. No retired consumer is sampled: batches 034–035 are maintained-to-retire records, including the formerly large doctrine, per L12-34(2). Their ids remain coverage.','', '## Review method and boundary','', '**Never run the checker or probes.** Read every assigned pinned consumer completely via `git show <pin>:<file>`, using bounded line chunks for long sources. Read each complete per-file diff and all edge fields through the Python extractor below. Do not `cat`, grep or print a whole JSONL record line. Independently inspect actual pinned targets, literal/source carriage declarations, adjacent descriptions, relative coordinates and generated-source roles. A hash/author comparison is a binding, never semantic acceptance. Review every edge of the assigned file, including preserved/parked/row-flip and supplemental references; whole-file scan exclusions also need judgment.','', 'There are no generated-render or canonical core/skills consumers in these six scheduling sets. `step-03-wave2-generated-surfaces.json` binds classification of all 60 consumers. Do not import rendered skill files into this packet or infer that a doc discussing a skill is generated. Any generated surface discovered in actual review must park to its exact verified canonical source, never get a hand patch. Shipped prompt conventions for an external project remain literal (L12-10; notably master-coordinator’s when-present repository rules).','', 'Check migration paragraphs as units. Source-computed line/table/list boundaries control consistency; advisory ids cannot split a unit. Inside actual carriage there are no existence facts. Outside it, historical provenance, removed/renamed targets and non-executable notes must be true at the pin. Related wrappers are live navigation even on historical carriers; separate Superseded-by/retirement framing preserves. A whole-file target needs a real whole-file subject; specific claims require the smallest enclosing extractor heading with complete adjacent description truth.','', '## Python field extractor','', 'Set `consumer` and `batch` to an assigned row; run once per file. It prints fields individually, never a serialized record line. Use the exact report name assigned below.','', '```python', 'import json, pathlib', "root = pathlib.Path('plans/260925-documentation-authority-unification/reports/phase-08')", "batch = '038'", "consumer = 'COPY EXACT ASSIGNED CONSUMER PATH'", "record = next(json.loads(line) for line in (root/'step-03-records'/f'batch-{batch}.jsonl').read_text().splitlines() if json.loads(line)['file'] == consumer)", "for key in ('file','authorInputCommit','digest','inventoryEdgeIds','authoringRules','diff'):", "    print(key, record.get(key))", "for edge in record.get('edges', []):", "    for key in ('edgeId','sourceSpans','matchedExpression','disposition','target','anchor','reason','timing','diffHunk','blockedCategory','dependencyCategory','blockedReason','dependency','targetFacts','unitDispositionReason','authorAddedEdge','searchWitness'):", "        print(key, json.dumps(edge.get(key), ensure_ascii=False, indent=2))", "for section in ('coverage','anchors','relativeResolution','labelForm'):", "    value = record.get('checks', {}).get(section, {})", "    for key, proof in value.items():", "        print(section, key, json.dumps(proof, ensure_ascii=False, indent=2))", '```','', 'For a long source, use `git show <pin>:<consumer> | sed -n \'1,120p\'`, then consecutive chunks through EOF. For long `coverage.legacyScan.candidates`, iterate individual candidate fields or slice the candidate list; do not summarize away unreviewed edges. Every assigned record fits the existing ≤60-record / ≤400,000-byte human-payload limit. Measured source-plus-record parts are also ≤400,000 bytes; each part has ≤6 files / ≤150 edges.','', '## Per-set and per-stratum accounting','', '| Set | Retire / all | Patched population / seed sample | Mandatory | Patched+mandatory distinct | Unpatched eligible / sample | Review union |','|---|---:|---:|---:|---:|---:|---:|']
 for a in account:lines.append(f"| {a['set']} | {a['retiringFiles']}/{a['allFiles']} | {a['patchedPopulation']}/{a['patchedSeedSample']} | {a['mandatoryFiles']} | {a['patchedAndMandatoryDistinct']} | {a['unpatchedEligiblePopulation']}/{a['unpatchedSample']} | {a['distinctSelected']} |")
 lines+=['','Unpatched eligibility excludes files already selected as patched/mandatory and requires an empty diff plus ≥1 edge. Zero-edge files remain in the manifest. Record reviewed-file denominators and rework numerators separately for each set and stratum; a file needing any semantic correction counts once. ≤3% passes that sample gate; >3% expands to every surviving file of that set, including parks/preserves/zero-edge files. Never pool sets, replace failed samples, silently reseed or treat authored mechanical green as semantic acceptance.','', '## Assigned parts','']
 for part in result['parts']:
  lines += [f"### Part {part['part']:02} → `{pathlib.Path(part['report']).name}`",'',f"{part['fileCount']} whole files / {part['edges']} edges / {part['sourcePlusRecordBytes']:,} source-plus-record bytes.",'','| Set | Consumer | Stratum | Edges |','|---|---|---|---:|']
  for row in part['files']:lines.append(f"| {row['set']} | `{row['file']}` | {', '.join(row['strata'])} | {row['edges']} |")
  lines.append('')
 lines += ['## Required report and handoff','','Write only the assigned unique review report within this plan. State pin, complete reading method, record/diff hashes, per-file verdict and edges read. Separate outcome defects (required rework) from record-text notes and questions needing Lead judgment. Report numerator/denominator per set and stratum; no pooled pass. Keep dissent and exact source/target line evidence. Do not author repairs, run checker/probes, launch other reviewers or self-accept the author packet.','','Lead owns independent dispatch/acceptance, actual runner-commit accounting in both protected Phase 6 manifests and committed-byte proof. Step 5 parity, RUL10/workflow/GAP-02 carry and Phase 9 authorization remain outstanding. L12-36(4) notes remain with the Step 10 reading-map merge/semantic-remnant owner. No new Lead-ruling gap was required to author this packet. Names are the exact brief-authorized `review-a38-step-03-wave2-pNN.md` namespace; this worker cannot call the forbidden fgOS convention CLI or start a preview service.']
 (P/'step-03-wave2-review-request.md').write_text('\n'.join(lines)+'\n')
 print(json.dumps({'files':len(rows),'edges':result['selectedEdges'],'parts':[{'report':x['report'],'files':x['fileCount'],'edges':x['edges'],'bytes':x['sourcePlusRecordBytes']} for x in result['parts']]},ensure_ascii=False,indent=2))
if __name__=='__main__':main()
